  const [moduleLogsLoading, setModuleLogsLoading] = useState(false);
  const [moduleLogsAutoRefresh, setModuleLogsAutoRefresh] = useState(false);
  // ── Module hub ────────────────────────────────────────────────────
  // Landing grid of every module: pick one to start editing it, with a live
  // online/offline dot per module. Statuses are probed in the background while
  // the hub is open (app port via the same-origin /api/service route, API via
  // its /health). `autoRestartAfterEdit` restarts a module through pm2 as soon
  // as an edit job targeting it completes, so changes actually take effect.
  const [moduleStatuses, setModuleStatuses] = useState<Record<string, { app: boolean | null; api: boolean | null }>>({});
  const [hubSearch, setHubSearch] = useState("");
  // Hub layout: "grid" is the card wall; "graph" lays modules out by their
  // declared `deps` (config.json) as a dependency graph, leaving modules with
  // no edges as isolated nodes.
  const [hubGraphMode, setHubGraphMode] = useState(false);
  // Hub previews: each card wears a live screenshot of the module's own web
  // page (same capture the avatar uses, just full-bleed), so the wall reads
  // as the fleet's websites instead of a list of names. On by default;
  // persisted, because it's a taste call, not a per-visit one.
  const [hubPreview, setHubPreview] = useState(true);
  // Hub status filter: every module, only ones with a live app/api probe, or
  // only ones without. "stopped" includes not-yet-probed modules — anything
  // not confirmed live — so the split always covers the whole grid.
  const [hubRunFilter, setHubRunFilter] = useState<"all" | "running" | "stopped">("all");
  // Hub sort: "live" floats online modules first (the original behavior),
  // "updated" is newest-edited first (file mtime from /modules), "name" is
  // plain A-Z. Persisted — a few bytes, safeSetItem guards the shared quota.
  const [hubSort, setHubSort] = useState<"live" | "updated" | "name">("live");
  // The hub browses MODULES, full stop — the console's editing, process and
  // snapshot surfaces are all module-shaped, so a second browse mode in front
  // of them was a door you had to close before you could work.
  // MCP filter: every module that answers the Model Context Protocol, i.e.
  // the ones an agent can drive without a human in the console.
  const [hubMcpFilter, setHubMcpFilter] = useState(false);
  // Visibility filter: every module is PUBLIC until its owner opts out, and a
  // private one is only ever on YOUR hub — so this pill answers "what am I
  // actually showing the world?" without opening a module at a time.
  const [hubVisFilter, setHubVisFilter] = useState<"all" | "public" | "private">("all");
  // What build's own APP tab shows. This console can't iframe itself (see
  // `homeInstead`), so that pane renders something native — and the front of
  // this app IS the hub, the same card wall you land on at /build-fork. HOME (the
  // quick-start / frameworks / jump-back-in page) stays one click away in the
  // tab's control row. Persisted: a taste call, not a per-visit one.
  const [selfAppView, setSelfAppView] = useState<"hub" | "home">("hub");
  // Hub tree tabs: the scan roots (orbit/, core/) are tabs, not a prefix on
  // every card title. null = all trees.
  const [hubTreeFilter, setHubTreeFilter] = useState<string | null>(null);
  // Same module name published by DIFFERENT owners collapses into one hub
  // card with an owner picker. Maps name → path of the copy being shown;
  // not persisted, so every load defaults back to YOUR copy when you own one.
  const [hubOwnerPick, setHubOwnerPick] = useState<Record<string, string>>({});
  // Anchor for the owner-picker popover (fixed-position — .hub-card clips
  // overflow, so the menu can't live inside the card).
  const [hubOwnerMenu, setHubOwnerMenu] = useState<{ name: string; x: number; y: number } | null>(null);
  // Cache-buster per module for the preview shots: bumping it re-requests the
  // capture with ?refresh=1 (the API still enforces its own refresh floor).
  const [hubShotBust, setHubShotBust] = useState<Record<string, number>>({});
  // Module whose privacy sheet is open (public ⇄ private + key desk), by name.
  const [privacyModule, setPrivacyModule] = useState<string | null>(null);
  const [autoRestartAfterEdit, setAutoRestartAfterEdit] = useState(true);
  // ── Add-Module modal: import a fresh module from a GitHub repo or a
  //    snapshot CID (POST /modules/import). ───────────────────────────
  const [addOpen, setAddOpen] = useState(false);
  const [addSource, setAddSource] = useState<"github" | "cid">("github");
  const [addUrl, setAddUrl] = useState("");
  const [addCid, setAddCid] = useState("");
  const [addName, setAddName] = useState("");
  const [addBusy, setAddBusy] = useState(false);
  const [addError, setAddError] = useState<string | null>(null);
  // Fork/copy-a-module modal — deterministic server-side copy of any module's
  // LIVE tree into a new name (POST /modules/:name/copy). No AI job, no CID:
  // files copy instantly and the new config gets fresh ports, so the copy is
  // the user's to reshape however they want.
  const [copyFrom, setCopyFrom] = useState<string | null>(null);
  const [copyNewName, setCopyNewName] = useState("");
  const [copyBusy, setCopyBusy] = useState(false);
  const [copyError, setCopyError] = useState<string | null>(null);
  const [restartNotice, setRestartNotice] = useState<string | null>(null);
  // Module process state, shown as a chip INSIDE the app/api control row
  // rather than as a floating toast. The toast used to land dead center
  // over the previewed app's own header after every edit — a popup you
  // have to wait out to see the thing you just changed. Restarting is a
  // fact about the module in the frame, so it belongs in that module's
  // own row; a clean restart says nothing at all (the health dots and
  // the reloaded frame already tell that story), only in-flight and
  // failure are worth a word.
  const [restartState, setRestartState] = useState<
    { name: string; phase: "busy" | "failed"; detail?: string } | null
  >(null);
  const prevJobStatusRef = useRef<Record<string, string>>({});
  const [expandedAsks, setExpandedAsks] = useState<Set<string>>(new Set());
  const [expandedPrompts, setExpandedPrompts] = useState<Set<string>>(new Set());
  const [expandedJobImage, setExpandedJobImage] = useState<string | null>(null);
  const [images, setImages] = useState<Array<{ name: string; data: string }>>(
    []
  );
  // Click the "N IMG" chip to see what's actually attached — a lightbox over
  // the composer showing the pending images (data URLs, no server fetch).
  const [imagePreviewIdx, setImagePreviewIdx] = useState<number | null>(null);
  // Attach images via the OS file picker — the phone path. accept="image/*"
  // (no capture attr) opens Photo Library / Take Photo on iOS and Android,
  // which is where screenshots land; paste stays the desktop shortcut. Both
  // routes feed the same images state the composers submit.
  const addImageFiles = (files: FileList | File[] | null) => {
    if (!files) return;
    for (const file of Array.from(files)) {
      if (!file.type.startsWith("image/")) continue;
      const reader = new FileReader();
      reader.onload = () => {
        const base64 = reader.result as string;
        setImages((prev) => [...prev, { name: file.name || `image-${Date.now()}.png`, data: base64 }]);
      };
      reader.readAsDataURL(file);
    }
  };
  const composerImageInputRef = useRef<HTMLInputElement>(null);
  const bandImageInputRef = useRef<HTMLInputElement>(null);
  // The ask band's 📷 menu: upload an image + the APP SNAP toggle, so both
  // are reachable on a phone where the full composer's toolbar isn't.
  const [attachMenuOpen, setAttachMenuOpen] = useState(false);
  const attachMenuRef = useRef<HTMLDivElement>(null);
  // Snap-on-submit: when ON, each submitted task gets a fresh screenshot of
  // the selected module's app page attached as an image, so the agent sees
  // what the app looks like at the moment of the request. ON by default;
  // turning it off is persisted ("0") and honored on load.
  const [snapAppOnSubmit, setSnapAppOnSubmit] = useState(true);
  // Hide the whole console header (address bar + tab strip) for a chrome-free
  // view of the app. Hiding is persisted ("1"); a small floating ▾ chip in the
  // top-right corner brings it back.
  const [headerHidden, setHeaderHidden] = useState(false);
  const [theme, setTheme] = useState<ThemeId>("gameboy");
  // Typeface, chosen independently of the palette (see FONTS).
  const [font, setFont] = useState<FontId>("default");
  // Theme picker popup, pinned in the tab row next to SPLIT.
  const [themeMenuOpen, setThemeMenuOpen] = useState(false);
  const [showUserDetails, setShowUserDetails] = useState(false);
  const [showVersions, setShowVersions] = useState(false);

  // Snapshot chain of the currently-selected module — polls every 30s and
  // drives the versions count badge; the full VersionsPanel handles
  // fork/restore actions.
  type VersionChainEntry = {
    cid: string;
    message: string;
    author: string;
    timestamp: number;
    parent: string | null;
    action?: string;
  };
  const [agentVersions, setAgentVersions] = useState<VersionChainEntry[]>([]);

  // Owner-managed whitelist of EOAs that may sign in to this module.
  // Backed by GET/POST/DELETE /whitelist on the Rust API. Non-owners
  // see the list read-only; owner gets a delete X per row + an add box.
  const [whitelist, setWhitelist] = useState<string[]>([]);
  const [whitelistInput, setWhitelistInput] = useState("");
  const [whitelistBusy, setWhitelistBusy] = useState(false);
  const [whitelistError, setWhitelistError] = useState<string | null>(null);

  // ── Time-boxed edit grants (QR hand-off) ──────────────────────────
  // The owner mints a grant → a QR-shareable invite that confers temporary
  // edit access (default 1h), optionally gated by a locally-generated key the
  // owner shares out of band, and optionally scoped to a module whitelist
  // (null/[] = every module). Backed by GET/POST/DELETE /grants on the API.
  type GrantRow = { id: string; exp: number; ttl: number; label?: string | null; created: number; key_required: boolean; modules?: string[] | null };
  type RedemptionRow = { address: string; exp: number; grant: string; redeemed: number; modules?: string[] | null };
  const [grants, setGrants] = useState<GrantRow[]>([]);
  const [grantRedemptions, setGrantRedemptions] = useState<RedemptionRow[]>([]);
  const [grantTtl, setGrantTtl] = useState(3600); // seconds; default 1h
  const [grantTtlText, setGrantTtlText] = useState("1"); // duration in hours, as typed
  const [grantKey, setGrantKey] = useState("");
  const [grantLabel, setGrantLabel] = useState("");
  // Module scope for the next invite. Scoped is the DEFAULT and seeds itself
  // with the module you're looking at: "let them fix this mod" is the common
  // case, and an unscoped invite hands over the whole tree. [] with scoping
  // on is refused client-side rather than silently meaning EVERYTHING.
  const [grantModules, setGrantModules] = useState<string[]>([]);
  const [grantScoped, setGrantScoped] = useState(true);
  // Filter text for the module picker — the fleet catalog is long.
  const [grantModFilter, setGrantModFilter] = useState("");
  const [grantBusy, setGrantBusy] = useState(false);
  const [grantError, setGrantError] = useState<string | null>(null);
  // The just-minted grant we're showing a QR for (id + the key to share OOB).
  const [activeGrant, setActiveGrant] = useState<{ id: string; exp: number; key?: string; key_required: boolean } | null>(null);
  const [grantCopied, setGrantCopied] = useState<string | null>(null);
  // Now (seconds) ticking for live countdowns on grants.
  const [nowSec, setNowSec] = useState(() => Math.floor(Date.now() / 1000));

  // Redemption side: an invite link (`?grant=<id>`) lands a non-owner here.
  // We capture it on mount and offer a "redeem" banner that threads the grant
  // through sign-in. The key (if required) is typed by the visitor.
  const [pendingGrant, setPendingGrant] = useState<string | null>(null);
  const [redeemKey, setRedeemKey] = useState("");
  const pendingGrantRef = useRef<{ id: string; key: string } | null>(null);
  // Walletless guest sessions (POST /grants/:id/redeem): unix expiry of the
  // guest access, driving the countdown pill + auto sign-out at grant end.
  const [guestExp, setGuestExp] = useState<number | null>(null);

  // ── Phone sign-in (session handoff QR) ─────────────────────────────
  // A signed-in browser mints a single-use code bound to its OWN identity
  // (POST /auth/handoff, minter-picked TTL clamped server-side); scanning the
  // QR opens `?handoff=<code>`, which the mount hook below trades for a
  // bearer token as the SAME address — so your phone signs in without a
  // wallet or any signing. Distinct from grants, which invite someone ELSE in.
  const [handoff, setHandoff] = useState<{ code: string; exp: number } | null>(null);
  const [handoffTtl, setHandoffTtl] = useState(300);
  const [handoffBusy, setHandoffBusy] = useState(false);
  const [handoffError, setHandoffError] = useState<string | null>(null);

  // What a live invite opens for THIS session (GET /role → invite_scope):
  // "all" (an unscoped invite), the module names a scoped invite named, or
  // null when we hold no invite. The owner needs none of this; for everyone
  // else it's the difference between editing a module and being told to go
  // work in peers/.
  const [inviteScope, setInviteScope] = useState<"all" | string[] | null>(null);

  // Which tier this session sits in (GET /auth/role → role). Any key may sign
  // in; one that isn't the owner, whitelisted, or holding an invite is a
  // "viewer" — the API refuses every write from it, so the console shows the
  // read-only truth instead of buttons that 403.
  const [role, setRole] = useState<"owner" | "editor" | "viewer" | null>(null);
  // Revert authority — narrower than `isOwner`. The API only lets the owner's
  // own key roll a module back to an earlier version; delegated sudo, the
  // whitelist and live invites all buy edit rights and stop there. Keeping it
  // as its own flag means the console shows the undo controls to exactly the
  // session the server will honor.
  const [canRevert, setCanRevert] = useState(false);

  // ── Share-anything QR ───────────────────────────────────────────────
  // One overlay that turns any shareable string — a snapshot CID/hash, a
  // module's app link, an import deep-link — into a locally-rendered QR
  // (qrSvg; the payload never leaves the browser). `options` are alternate
  // payload forms the user flips between (APP / IMPORT / CID / …).
  type QrShareOption = { label: string; value: string; hint?: string };
  const [qrShare, setQrShare] = useState<{ title: string; options: QrShareOption[] } | null>(null);
  const [qrShareIdx, setQrShareIdx] = useState(0);
  const [qrShareCopied, setQrShareCopied] = useState(false);
  // The other direction: read a QR with the camera instead of drawing one.
  // `accept` filters what counts as a hit (an address, say) and `onResult`
  // gets the accepted value — see the whitelist card's SCAN button.
  const [qrScan, setQrScan] = useState<{
    title: string;
    hint?: string;
    rejectHint?: string;
    accept?: (text: string) => string | null;
    onResult: (value: string) => void;
  } | null>(null);
  // `?replay=<cid>` — a scanned task-QR: the task-bundle CID to fetch and
  // load into the composer, consumed once by the replay effect below.
  const [pendingReplay, setPendingReplay] = useState<string | null>(null);
  // `?task=<cid>` — the same bundle opened to *read* rather than to re-run:
  // the shared session lands in the task pane with its transcript.
  const [pendingTask, setPendingTask] = useState<string | null>(null);
  // A session opened from a shared link whose row isn't in this console's
  // ledger (minted elsewhere, or pruned here). The bundle is adapted to a
  // Job so the normal task pane renders it — with no local row behind it,
  // the pane's destructive actions stay hidden (see `jobIsLocal`).
  const [sharedTask, setSharedTask] = useState<Job | null>(null);

  // File viewer state — a splittable grid of panes: columns sit side-by-side
  // (split →) and each column stacks panes (split ↓). A pane collapses to a
  // slim bar; a column whose panes are all collapsed folds into a vertical
  // rail. An empty grid hands the tree the full width (old no-file state).
  type FilePane = { id: number; file: string; content: string; loading: boolean; collapsed: boolean };
  type FilePaneColumn = { id: number; panes: FilePane[] };
  const paneSeq = useRef(1);
  const [paneCols, setPaneCols] = useState<FilePaneColumn[]>([]);
  const [activePaneId, setActivePaneId] = useState<number | null>(null);
  const [editingPaneId, setEditingPaneId] = useState<number | null>(null);
  const [editBuffer, setEditBuffer] = useState("");
  const [savingFile, setSavingFile] = useState(false);
  // Inline search state
  const [inlineSearchMode, setInlineSearchMode] = useState<"off" | "files" | "grep">("files");
  const [inlineSearchQuery, setInlineSearchQuery] = useState("");
  const [inlineSearchResults, setInlineSearchResults] = useState<any[]>([]);
  const [inlineSearchLoading, setInlineSearchLoading] = useState(false);
  const [inlineSelectedIndex, setInlineSelectedIndex] = useState(0);
  const inlineSearchRef = useRef<HTMLInputElement>(null);

  // Token stats modal
  const [showTokenStats, setShowTokenStats] = useState(false);
